## Pages
1: Test setup (http://localhost:3000/dev) [selected]
## WebMCP tools
name="add_to_cart", description="Add one product in one size and color to the cart. Use a product id from search_products or get_product. Returns the updated cart.", inputSchema={"type":"object","properties":{"productId":{"type":"string","description":"Product id from search_products or get_product."},"size":{"type":"string","enum":["XS","S","M","L","XL"],"description":"Size, e.g. M."},"color":{"type":"string","description":"Color id from get_product, e.g. blue."},"quantity":{"type":"integer","minimum":1,"description":"How many to add. Defaults to 1."}},"required":["productId","size","color"]}, annotations=undefined
name="get_cart", description="Read the cart: every item with product id, name, size, color, quantity and unit price, plus the total in USD.", inputSchema={"type":"object","properties":{}}, annotations={"readOnly":true,"untrustedContent":false,"consequential":false,"debugging":false}
name="get_product", description="Get one product's description and its stock for every color and size. Use it to choose a size and color before adding to the cart.", inputSchema={"type":"object","properties":{"productId":{"type":"string","description":"Product id from search_products."}},"required":["productId"]}, annotations={"readOnly":true,"untrustedContent":true,"consequential":false,"debugging":false}
name="open_checkout", description="Open the checkout review page, which shows the cart and total. It does not place the order; the customer places it.", inputSchema={"type":"object","properties":{}}, annotations={"readOnly":false,"untrustedContent":false,"consequential":true,"debugging":false}
name="remove_from_cart", description="Remove one item from the cart, identified by product id, size and color. Returns the updated cart.", inputSchema={"type":"object","properties":{"productId":{"type":"string","description":"Product id from search_products or get_product."},"size":{"type":"string","enum":["XS","S","M","L","XL"],"description":"Size, e.g. M."},"color":{"type":"string","description":"Color id from get_product, e.g. blue."}},"required":["productId","size","color"]}, annotations=undefined
name="search_products", description="Search the store catalog by text, category, maximum price in USD or size. Returns up to 10 products with productId, name, price and the sizes in stock. Use it to find product ids.", inputSchema={"type":"object","properties":{"query":{"type":"string","description":"Words matched against name, description, tags, colors."},"category":{"type":"string","enum":["jackets","boots","socks","shirts"]},"maxPrice":{"type":"number","description":"Highest price in USD."},"size":{"type":"string","enum":["XS","S","M","L","XL"]}}}, annotations={"readOnly":true,"untrustedContent":true,"consequential":false,"debugging":false}

